import { NO_DECISION_SENTENCE } from "@constants/document";
import styled from "@emotion/styled";
import SourceRecording from "@features/document/SourceRecording";
import useConfirmDocument from "@hooks/domain/document/useConfirmDocument";
import Chip from "@primitives/ui/Chip";
import DocumentBody from "@primitives/ui/DocumentBody";
import { captureAnalyticsEvent } from "@utils/captureAnalyticsEvent";
import { formatDate } from "@utils/formatDate";
import { formatDurationFromSeconds } from "@utils/formatDurationFromSeconds";
import { useId } from "react";
import { useParams } from "react-router";

import { useDocumentViewer } from "./model/useDocumentViewer";
import DocumentConfirmButton from "./ui/DocumentConfirmButton";
import DocumentConfirmCount from "./ui/DocumentConfirmCount";
import DocumentCopyButton from "./ui/DocumentCopyButton";
import DocumentLoadFailed from "./ui/DocumentLoadFailed";
import DocumentSkeleton from "./ui/DocumentSkeleton";

/**
 * 문서 보기 섹션. 주소의 문서를 불러와 복사 버튼 · 제목 · 만든 날짜 · 녹음 길이 · 확인 수 · 본문 · 확인 버튼을 보여줘요.
 * 어느 문서를 보고 있는지는 본문 위가 아니라 GNB의 위치 표시가 `워크스페이스 이름 › 문서 › 문서 제목`으로 알려요(WS-R15).
 *
 * 주소의 두 id는 숫자인지 확인하지 않고 그대로 요청해요. 잘못된 주소인지는 서버가 판단하고, 여기서는 그 응답에 따라 문서를 불러오지 못했다고 알려요.
 * 같은 판단을 프론트에도 두면 기준이 두 곳에 생기기 때문이에요.
 *
 * 받은 문서 값을 그리기만 하면 되는 것(제목 · 날짜 · 녹음 길이 · 본문)은 여기서 직접 그려요.
 * 복사 버튼 · 확인 수 · 확인 버튼은 이 위젯의 부품(`ui/`)이고, 필요한 값과 동작을 여기서 넘겨줘요. 문서는 여기서 한 번만 조회해요.
 * 복사 버튼은 제목과 같은 줄의 오른쪽 끝에 놓아요.
 * 본문 아래에는 이 문서를 만든 녹음을 카드로 두고, 누르면 그 녹음의 녹음 문서로 가요(DOC-R25). 어느 입구로 열었든 같아요.
 * 그 아래 줄의 오른쪽 끝에 확인 버튼을 놓아요. 같은 녹음의 문서를 넘기는 이전 · 다음은 없어요(DOC-R2).
 * 확인 버튼은 확인 대상에게만 보여요. 확인한 뒤에는 누를 수 없는 「확인했어요」로 바뀌고, 확인 대상이 아니면 그 줄을 그리지 않아요.
 * 같은 녹음의 내 문서를 모두 확인하면 성공 토스트를, 확인 요청이 실패하면 오류 토스트를 띄워요(`useConfirmDocument`).
 * 결정이 없는 회의 문서는 본문의 결정 없음 문장을 흐리게 그려요(STT-R23).
 * 복사에 성공하면 문서 본문 복사를 사용 기록(`content_copied`)으로 보내요.
 */
export default function DocumentViewer() {
  const titleId = useId();
  const params = useParams();
  const workspaceId = Number(params.workspaceId);
  const documentId = Number(params.documentId);
  const { status, documentDetail, retry } = useDocumentViewer({
    workspaceId,
    documentId,
  });
  const { confirmDocument, isConfirming } = useConfirmDocument({
    workspaceId,
    documentId,
    recordingSessionId: documentDetail?.recordingSessionId,
  });

  const handleDocumentCopied = () => {
    captureAnalyticsEvent({
      event: "content_copied",
      properties: {
        content: "document",
        screen: "document",
        document_id: documentId,
        workspace_id: workspaceId,
      },
    });
  };

  if (status === "loading") {
    return (
      <Container aria-busy="true" aria-label="문서를 불러오고 있어요">
        <DocumentSkeleton />
      </Container>
    );
  }

  if (status === "error") {
    return <DocumentLoadFailed onRetry={retry} />;
  }

  return (
    // 다른 문서로 넘어가면 「복사됨」 같은 앞 문서의 표시가 남지 않게, 문서마다 새로 그려요
    <Container key={documentDetail.id} aria-labelledby={titleId}>
      <TitleBlock>
        <TitleRow>
          <Title id={titleId}>{documentDetail.title}</Title>
          <DocumentCopyButton
            title={documentDetail.title}
            content={documentDetail.content}
            onCopied={handleDocumentCopied}
          />
        </TitleRow>
        <MetaRow>
          <Meta>
            <CreatedDate dateTime={documentDetail.createdAt}>
              {formatDate(documentDetail.createdAt)}
            </CreatedDate>
            <Chip>
              {formatDurationFromSeconds(
                documentDetail.recordingDurationSeconds,
              )}
            </Chip>
          </Meta>
          <DocumentConfirmCount
            workspaceId={workspaceId}
            documentId={documentId}
            confirmedCount={documentDetail.confirmationSummary.confirmedCount}
          />
        </MetaRow>
      </TitleBlock>
      <DocumentBody
        content={documentDetail.content}
        mutedLines={[NO_DECISION_SENTENCE]}
      />
      <SourceRecording
        workspaceId={workspaceId}
        recordingId={documentDetail.recordingSessionId}
      />
      {documentDetail.myConfirmationState !== "NOT_REQUIRED" && (
        <ConfirmBar>
          <DocumentConfirmButton
            isConfirmed={documentDetail.myConfirmationState === "CONFIRMED"}
            isConfirming={isConfirming}
            onConfirm={confirmDocument}
          />
        </ConfirmBar>
      )}
    </Container>
  );
}

/** 피그마 문서 열(Standard): 폭 720px, 제목 묶음 · 본문 사이 24px */
const Container = styled.section`
  display: flex;
  flex-direction: column;
  gap: 1.5rem; /* 24px */
  width: 100%;
  max-width: 45rem; /* 720px */
`;

/** 피그마 TitleBlock: 제목 줄과 날짜 줄 사이 4px */
const TitleBlock = styled.div`
  display: flex;
  flex-direction: column;
  gap: 0.25rem; /* 4px */
`;

/** 피그마 TitleRow: 왼쪽에 제목, 오른쪽 끝에 복사 버튼. 둘 사이 16px, 세로 가운데 */
const TitleRow = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem; /* 16px */
`;

/** 제목이 길면 버튼 자리를 남기고 줄을 바꿔요 */
const Title = styled.h2`
  flex: 1;
  min-width: 0;
  ${({ theme }) => theme.text.heading02};
  color: ${({ theme }) => theme.neutral[900]};
  overflow-wrap: break-word;
`;

/** 피그마 MetaRow: 왼쪽에 날짜 · 녹음 길이, 오른쪽 끝에 확인 수 */
const MetaRow = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem; /* 8px */
`;

/** 피그마 Meta: 날짜와 녹음 길이 칩 사이 8px */
const Meta = styled.div`
  display: flex;
  align-items: center;
  gap: 0.5rem; /* 8px */
`;

const CreatedDate = styled.time`
  ${({ theme }) => theme.text.caption02};
  color: ${({ theme }) => theme.neutral[500]};
`;

/** 피그마 Confirm/하단 바: 본문 아래 구분선과 위아래 12px, 오른쪽 끝에 확인 버튼 */
const ConfirmBar = styled.div`
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 0.75rem 0; /* 12px 0 */
  border-top: 1px solid ${({ theme }) => theme.neutral[200]};
`;
